"""Tests for the CLI-vs-lockfile generator guard (microsoft/apm#2334).

Structured around the issue's acceptance evidence:

* a 0.24.0 CLI is rejected before writing a lockfile generated by 0.25.0;
* equal and newer CLIs continue normally;
* stable/prerelease ordering is covered;
* the rejected command leaves the lockfile byte-for-byte unchanged;
* the guard covers every mutating path, not only ``install``.
"""

from __future__ import annotations

from pathlib import Path

import pytest
import yaml
from click.testing import CliRunner

from apm_cli.deps.lockfile_guard import (
    StaleCliError,
    UnsafeGeneratorMetadataError,
    parse_version,
    read_recorded_generator,
    require_compatible_lockfile_generator,
)

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _write_lockfile(directory: Path, apm_version: str | None) -> Path:
    """Write a minimal lockfile, optionally recording *apm_version*."""
    body: dict[str, object] = {"lockfile_version": "1", "dependencies": {}}
    if apm_version is not None:
        body["apm_version"] = apm_version
    path = directory / "apm.lock.yaml"
    path.write_text(yaml.safe_dump(body), encoding="utf-8")
    return path


def _write_project(directory: Path, apm_version: str | None) -> Path:
    """Write an apm.yml + lockfile pair and return the lockfile path."""
    skill = directory / "skills" / "example"
    skill.mkdir(parents=True, exist_ok=True)
    (skill / "SKILL.md").write_text(
        "---\nname: example\ndescription: Fixture skill for the #2334 guard.\n---\n\n# Example\n",
        encoding="utf-8",
    )
    (directory / "apm.yml").write_text(
        "name: guard-fixture\n"
        "version: 0.1.0\n"
        "description: Fixture for the #2334 lockfile generator guard\n"
        "targets:\n  - agent-skills\n"
        "dependencies:\n  apm:\n    - path: ./skills/example\n  mcp: []\n"
        "includes: auto\nscripts: {}\n",
        encoding="utf-8",
    )
    return _write_lockfile(directory, apm_version)


# ---------------------------------------------------------------------------
# Version ordering (acceptance: stable/prerelease ordering is covered)
# ---------------------------------------------------------------------------


class TestVersionOrdering:
    def test_full_release_spectrum_is_monotonic(self) -> None:
        """a < b < rc < stable, and patch/minor/major dominate prereleases."""
        ascending = [
            "0.24.0",
            "0.25.0a1",
            "0.25.0a2",
            "0.25.0b1",
            "0.25.0rc1",
            "0.25.0",
            "0.25.1",
            "0.26.0",
            "1.0.0",
        ]
        keys = [parse_version(v) for v in ascending]
        assert all(k is not None for k in keys)
        assert all(keys[i] < keys[i + 1] for i in range(len(keys) - 1))

    def test_prerelease_number_compares_numerically(self) -> None:
        """``a10`` follows ``a9``; a lexicographic compare would invert these."""
        assert parse_version("0.25.0a10") > parse_version("0.25.0a9")

    def test_build_metadata_does_not_affect_precedence(self) -> None:
        assert parse_version("0.25.0+build.7") == parse_version("0.25.0")
        assert parse_version("0.25.0rc1+abc") == parse_version("0.25.0rc1")

    @pytest.mark.parametrize(
        "raw",
        ["0.0.0-test", "test", "unknown", "", "1.2", "v1.2.3", "1.2.3.4", None, 3],
    )
    def test_unparseable_values_return_none(self, raw: object) -> None:
        assert parse_version(raw) is None


# ---------------------------------------------------------------------------
# Recorded metadata (acceptance: malformed/duplicate treated as unsafe)
# ---------------------------------------------------------------------------


class TestRecordedGenerator:
    def test_absent_lockfile_reads_as_none(self, tmp_path: Path) -> None:
        assert read_recorded_generator(tmp_path / "apm.lock.yaml") is None

    def test_lockfile_without_apm_version_reads_as_none(self, tmp_path: Path) -> None:
        """Lockfiles predating the field are legacy, not corrupt."""
        assert read_recorded_generator(_write_lockfile(tmp_path, None)) is None

    def test_recorded_version_is_returned(self, tmp_path: Path) -> None:
        assert read_recorded_generator(_write_lockfile(tmp_path, "0.25.0")) == "0.25.0"

    def test_duplicate_top_level_keys_are_unsafe(self, tmp_path: Path) -> None:
        """YAML resolves duplicates silently, so the true generator is unknowable."""
        path = _write_lockfile(tmp_path, "0.25.0")
        path.write_text(
            path.read_text(encoding="utf-8") + "apm_version: 0.24.0\n", encoding="utf-8"
        )
        with pytest.raises(UnsafeGeneratorMetadataError, match="2 times"):
            read_recorded_generator(path)

    def test_indented_apm_version_is_not_the_top_level_field(self, tmp_path: Path) -> None:
        """A nested key of the same name must not be mistaken for a duplicate."""
        path = _write_lockfile(tmp_path, "0.25.0")
        path.write_text(
            path.read_text(encoding="utf-8") + "dependencies:\n  pkg:\n    apm_version: 0.1.0\n",
            encoding="utf-8",
        )
        assert read_recorded_generator(path) == "0.25.0"


# ---------------------------------------------------------------------------
# The guard itself
# ---------------------------------------------------------------------------


class TestGuard:
    def test_older_cli_is_rejected(self, tmp_path: Path) -> None:
        """The issue's reported case: 0.24.0 against a 0.25.0-generated lockfile."""
        path = _write_lockfile(tmp_path, "0.25.0")
        with pytest.raises(StaleCliError) as excinfo:
            require_compatible_lockfile_generator(path, running_version="0.24.0")
        # Acceptance: the error names both versions.
        assert "0.25.0" in str(excinfo.value)
        assert "0.24.0" in str(excinfo.value)
        assert excinfo.value.running == "0.24.0"
        assert excinfo.value.recorded == "0.25.0"

    @pytest.mark.parametrize("running", ["0.25.0", "0.25.1", "0.26.0", "1.0.0"])
    def test_equal_and_newer_cli_proceeds(self, tmp_path: Path, running: str) -> None:
        path = _write_lockfile(tmp_path, "0.25.0")
        require_compatible_lockfile_generator(path, running_version=running)

    def test_prerelease_cli_is_older_than_its_stable_release(self, tmp_path: Path) -> None:
        path = _write_lockfile(tmp_path, "0.25.0")
        with pytest.raises(StaleCliError):
            require_compatible_lockfile_generator(path, running_version="0.25.0rc1")

    def test_stable_cli_supersedes_a_prerelease_generator(self, tmp_path: Path) -> None:
        path = _write_lockfile(tmp_path, "0.25.0rc1")
        require_compatible_lockfile_generator(path, running_version="0.25.0")

    def test_missing_lockfile_is_a_no_op(self, tmp_path: Path) -> None:
        """First install: nothing to compare against."""
        require_compatible_lockfile_generator(tmp_path / "apm.lock.yaml", running_version="0.24.0")

    def test_legacy_lockfile_without_field_is_a_no_op(self, tmp_path: Path) -> None:
        require_compatible_lockfile_generator(
            _write_lockfile(tmp_path, None), running_version="0.24.0"
        )

    def test_unknown_sentinel_is_treated_as_absent(self, tmp_path: Path) -> None:
        """APM writes ``unknown`` itself; refusing it would brick its own lockfiles."""
        require_compatible_lockfile_generator(
            _write_lockfile(tmp_path, "unknown"), running_version="0.24.0"
        )

    def test_malformed_recorded_version_is_unsafe(self, tmp_path: Path) -> None:
        path = _write_lockfile(tmp_path, "0.0.0-test")
        with pytest.raises(UnsafeGeneratorMetadataError, match="unrecognizable"):
            require_compatible_lockfile_generator(path, running_version="0.24.0")

    def test_undeterminable_running_version_is_unsafe(self, tmp_path: Path) -> None:
        """We cannot prove this CLI is not the older one, so we refuse."""
        path = _write_lockfile(tmp_path, "0.25.0")
        with pytest.raises(UnsafeGeneratorMetadataError, match="cannot"):
            require_compatible_lockfile_generator(path, running_version="unknown")

    def test_refusal_is_not_a_lockfile_format_error(self, tmp_path: Path) -> None:
        """Acceptance: CLI-compatibility failures stay distinct from schema ones."""
        from apm_cli.deps.lockfile import LockfileFormatError

        path = _write_lockfile(tmp_path, "0.25.0")
        with pytest.raises(StaleCliError) as excinfo:
            require_compatible_lockfile_generator(path, running_version="0.24.0")
        assert not isinstance(excinfo.value, LockfileFormatError)


# ---------------------------------------------------------------------------
# Every mutating path (acceptance: not only ``install``)
# ---------------------------------------------------------------------------

# Commands that can persist apm.lock.yaml, with arguments sufficient to reach
# the guard. Read-only commands (audit, outdated, deps, doctor, view, ...) are
# deliberately absent: the guard must not block them.
MUTATING_INVOCATIONS = [
    ("install", ["--no-policy"]),
    ("update", ["--yes"]),
    ("uninstall", ["./skills/example"]),
    ("prune", []),
    ("lock", []),
]


class TestEveryMutatingCommandIsGuarded:
    @pytest.mark.parametrize(
        ("command", "args"),
        MUTATING_INVOCATIONS,
        ids=[name for name, _ in MUTATING_INVOCATIONS],
    )
    def test_mutating_command_refuses_and_leaves_lockfile_untouched(
        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch, command: str, args: list[str]
    ) -> None:
        from apm_cli.cli import cli

        monkeypatch.chdir(tmp_path)
        lockfile = _write_project(tmp_path, "0.25.0")
        monkeypatch.setattr("apm_cli.deps.lockfile.installed_apm_version", lambda: "0.24.0")
        before = lockfile.read_bytes()

        result = CliRunner().invoke(cli, [command, *args])

        assert result.exit_code != 0, result.output
        assert "0.25.0" in result.output and "0.24.0" in result.output
        # Acceptance: the rejected command leaves the lockfile byte-for-byte
        # unchanged.
        assert lockfile.read_bytes() == before

    @pytest.mark.parametrize(
        ("command", "args"),
        MUTATING_INVOCATIONS,
        ids=[name for name, _ in MUTATING_INVOCATIONS],
    )
    def test_mutating_command_proceeds_past_guard_when_cli_is_newer(
        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch, command: str, args: list[str]
    ) -> None:
        """A newer CLI must not be stopped by the guard.

        The command may still fail for unrelated reasons in this minimal
        fixture, so this asserts only that no generator refusal was rendered.
        """
        from apm_cli.cli import cli

        monkeypatch.chdir(tmp_path)
        _write_project(tmp_path, "0.25.0")
        monkeypatch.setattr("apm_cli.deps.lockfile.installed_apm_version", lambda: "0.26.0")

        result = CliRunner().invoke(cli, [command, *args])

        assert "Refusing to rewrite" not in result.output
